// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

/** Initialize EntryPointContract
  *
  * guarantee CR01_MM_Init
  *   ModeManager_Req_Init: start in Init with zero activations; mode DataPort initialized to Init.
  * @param activationCount post-state state variable
  * @param currentMode post-state state variable
  * @param api_CurrentMode outgoing data port
  */
pub fn initialize_CR01_MM_Init(
  activationCount: i32,
  currentMode: SW::Mode,
  api_CurrentMode: SW::Mode) -> bool
{
  (currentMode == SW::Mode::Init) &
    (activationCount == 0i32) &
    (api_CurrentMode == SW::Mode::Init)
}

/** IEP-Guar: Initialize Entrypoint for ModeManager
  *
  * @param activationCount post-state state variable
  * @param currentMode post-state state variable
  * @param api_CurrentMode outgoing data port
  */
pub fn initialize_IEP_Guar(
  activationCount: i32,
  currentMode: SW::Mode,
  api_CurrentMode: SW::Mode) -> bool
{
  initialize_CR01_MM_Init(activationCount, currentMode, api_CurrentMode)
}

/** IEP-Post: Initialize Entrypoint Post-Condition
  *
  * @param activationCount post-state state variable
  * @param currentMode post-state state variable
  * @param api_CurrentMode outgoing data port
  */
pub fn initialize_IEP_Post(
  activationCount: i32,
  currentMode: SW::Mode,
  api_CurrentMode: SW::Mode) -> bool
{
  initialize_IEP_Guar(activationCount, currentMode, api_CurrentMode)
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_MM_Count
  *   ModeManager_Req_Count: activation counter increments each dispatch, saturating at 10.
  * @param In_activationCount pre-state state variable
  * @param activationCount post-state state variable
  */
pub fn compute_spec_CR01_MM_Count_guarantee(
  In_activationCount: i32,
  activationCount: i32) -> bool
{
  (implies!(
    (In_activationCount < 10i32),
    (activationCount == In_activationCount + 1i32))) &
    (implies!(
      (In_activationCount >= 10i32),
      (activationCount == In_activationCount)))
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_MM_Absorbing
  *   ModeManager_Req_Absorbing: RTL is absorbing until restart (RD-3).
  * @param In_currentMode pre-state state variable
  * @param currentMode post-state state variable
  */
pub fn compute_spec_CR01_MM_Absorbing_guarantee(
  In_currentMode: SW::Mode,
  currentMode: SW::Mode) -> bool
{
  implies!(
    (In_currentMode == SW::Mode::RTL),
    (currentMode == SW::Mode::RTL))
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_MM_ToRTL
  *   ModeManager_Req_ToRTL: when not already in RTL and either firewall reports Attack, enter RTL (wins ties against Init-to-Normal).
  * @param In_currentMode pre-state state variable
  * @param currentMode post-state state variable
  * @param api_AttackStatusRx incoming data port
  * @param api_AttackStatusTx incoming data port
  */
pub fn compute_spec_CR01_MM_ToRTL_guarantee(
  In_currentMode: SW::Mode,
  currentMode: SW::Mode,
  api_AttackStatusRx: SW::AttackStatus,
  api_AttackStatusTx: SW::AttackStatus) -> bool
{
  implies!(
    !(In_currentMode == SW::Mode::RTL) &
      (GumboLib::isAttack(api_AttackStatusRx) | GumboLib::isAttack(api_AttackStatusTx)),
    (currentMode == SW::Mode::RTL))
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_MM_StayInit
  *   ModeManager_Req_StayInit: in Init with no attack and (post-increment) count below 10, remain in Init.
  * @param In_currentMode pre-state state variable
  * @param activationCount post-state state variable
  * @param currentMode post-state state variable
  * @param api_AttackStatusRx incoming data port
  * @param api_AttackStatusTx incoming data port
  */
pub fn compute_spec_CR01_MM_StayInit_guarantee(
  In_currentMode: SW::Mode,
  activationCount: i32,
  currentMode: SW::Mode,
  api_AttackStatusRx: SW::AttackStatus,
  api_AttackStatusTx: SW::AttackStatus) -> bool
{
  implies!(
    (In_currentMode == SW::Mode::Init) &
      !(GumboLib::isAttack(api_AttackStatusRx) | GumboLib::isAttack(api_AttackStatusTx)) &
      (activationCount < 10i32),
    (currentMode == SW::Mode::Init))
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_MM_ToNormal
  *   ModeManager_Req_ToNormal: in Init with no attack and (post-increment) count reaching 10, transition to Normal.
  * @param In_currentMode pre-state state variable
  * @param activationCount post-state state variable
  * @param currentMode post-state state variable
  * @param api_AttackStatusRx incoming data port
  * @param api_AttackStatusTx incoming data port
  */
pub fn compute_spec_CR01_MM_ToNormal_guarantee(
  In_currentMode: SW::Mode,
  activationCount: i32,
  currentMode: SW::Mode,
  api_AttackStatusRx: SW::AttackStatus,
  api_AttackStatusTx: SW::AttackStatus) -> bool
{
  implies!(
    (In_currentMode == SW::Mode::Init) &
      !(GumboLib::isAttack(api_AttackStatusRx) | GumboLib::isAttack(api_AttackStatusTx)) &
      (activationCount >= 10i32),
    (currentMode == SW::Mode::Normal))
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_MM_StayNormal
  *   ModeManager_Req_StayNormal: in Normal with no attack, remain in Normal.
  * @param In_currentMode pre-state state variable
  * @param currentMode post-state state variable
  * @param api_AttackStatusRx incoming data port
  * @param api_AttackStatusTx incoming data port
  */
pub fn compute_spec_CR01_MM_StayNormal_guarantee(
  In_currentMode: SW::Mode,
  currentMode: SW::Mode,
  api_AttackStatusRx: SW::AttackStatus,
  api_AttackStatusTx: SW::AttackStatus) -> bool
{
  implies!(
    (In_currentMode == SW::Mode::Normal) &
      !(GumboLib::isAttack(api_AttackStatusRx) | GumboLib::isAttack(api_AttackStatusTx)),
    (currentMode == SW::Mode::Normal))
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_MM_Broadcast
  *   ModeManager_Req_Broadcast: the mode DataPort output equals the post-transition mode state.
  * @param currentMode post-state state variable
  * @param api_CurrentMode outgoing data port
  */
pub fn compute_spec_CR01_MM_Broadcast_guarantee(
  currentMode: SW::Mode,
  api_CurrentMode: SW::Mode) -> bool
{
  api_CurrentMode == currentMode
}

/** CEP-T-Guar: Top-level guarantee contracts for ModeManager's compute entrypoint
  *
  * @param In_activationCount pre-state state variable
  * @param In_currentMode pre-state state variable
  * @param activationCount post-state state variable
  * @param currentMode post-state state variable
  * @param api_AttackStatusRx incoming data port
  * @param api_AttackStatusTx incoming data port
  * @param api_CurrentMode outgoing data port
  */
pub fn compute_CEP_T_Guar(
  In_activationCount: i32,
  In_currentMode: SW::Mode,
  activationCount: i32,
  currentMode: SW::Mode,
  api_AttackStatusRx: SW::AttackStatus,
  api_AttackStatusTx: SW::AttackStatus,
  api_CurrentMode: SW::Mode) -> bool
{
  let r0: bool = compute_spec_CR01_MM_Count_guarantee(In_activationCount, activationCount);
  let r1: bool = compute_spec_CR01_MM_Absorbing_guarantee(In_currentMode, currentMode);
  let r2: bool = compute_spec_CR01_MM_ToRTL_guarantee(In_currentMode, currentMode, api_AttackStatusRx, api_AttackStatusTx);
  let r3: bool = compute_spec_CR01_MM_StayInit_guarantee(In_currentMode, activationCount, currentMode, api_AttackStatusRx, api_AttackStatusTx);
  let r4: bool = compute_spec_CR01_MM_ToNormal_guarantee(In_currentMode, activationCount, currentMode, api_AttackStatusRx, api_AttackStatusTx);
  let r5: bool = compute_spec_CR01_MM_StayNormal_guarantee(In_currentMode, currentMode, api_AttackStatusRx, api_AttackStatusTx);
  let r6: bool = compute_spec_CR01_MM_Broadcast_guarantee(currentMode, api_CurrentMode);

  return r0 && r1 && r2 && r3 && r4 && r5 && r6;
}

/** CEP-Post: Compute Entrypoint Post-Condition for ModeManager
  *
  * @param In_activationCount pre-state state variable
  * @param In_currentMode pre-state state variable
  * @param activationCount post-state state variable
  * @param currentMode post-state state variable
  * @param api_AttackStatusRx incoming data port
  * @param api_AttackStatusTx incoming data port
  * @param api_CurrentMode outgoing data port
  */
pub fn compute_CEP_Post(
  In_activationCount: i32,
  In_currentMode: SW::Mode,
  activationCount: i32,
  currentMode: SW::Mode,
  api_AttackStatusRx: SW::AttackStatus,
  api_AttackStatusTx: SW::AttackStatus,
  api_CurrentMode: SW::Mode) -> bool
{
  // CEP-Guar: guarantee clauses of ModeManager's compute entrypoint
  let r0: bool = compute_CEP_T_Guar(In_activationCount, In_currentMode, activationCount, currentMode, api_AttackStatusRx, api_AttackStatusTx, api_CurrentMode);

  return r0;
}
